  _confuse.push(
    {
      id: "cf01",
      title: { ja: "成長 と 価値創造", en: "Growth vs Value Creation" },
      wrong: { ja: "成長すれば必ず企業価値が高まる。", en: "Growth always increases corporate value." },
      right: { ja: "成長は価値中立。ROICが資本コストを下回る成長は規模拡大でも価値を破壊する。", en: "Growth is value-neutral; growing at sub-cost-of-capital returns destroys value despite scale." },
    },
    {
      id: "cf02",
      title: { ja: "利益 と キャッシュ", en: "Profit vs Cash" },
      wrong: { ja: "黒字なら資金繰りは問題ない。", en: "If profitable, liquidity is never a problem." },
      right: { ja: "利益とキャッシュは別物。黒字でも運転資本増や返済で資金が尽きれば倒産しうる。", en: "Profit and cash differ; a profitable firm can still fail if working capital or debt drains its cash." },
    },
    {
      id: "cf03",
      title: { ja: "EV と エクイティ価値", en: "EV vs Equity Value" },
      wrong: { ja: "EVがそのまま株主が受け取る対価。", en: "EV is what shareholders receive directly." },
      right: { ja: "エクイティ対価=EV−純負債等。デットライク・現金・NWC調整を経て株式対価が決まる。", en: "Equity = EV − net debt etc.; the equity price emerges after debt-like, cash, and NWC adjustments." },
    },
    {
      id: "cf04",
      title: { ja: "自社株買いは常に株主に good", en: "Buybacks Are Always Good" },
      wrong: { ja: "自社株買いはいつでも1株価値を高める。", en: "Buybacks always raise per-share value." },
      right: { ja: "本源価値を下回る価格でこそ価値創出。割高で買えば残存株主の価値を破壊する。", en: "Buybacks add value only below intrinsic value; overpaying destroys remaining holders' value." },
    },
    {
      id: "cf05",
      title: { ja: "リスク管理 と リスクをゼロにすること", en: "Risk Management vs Zero Risk" },
      wrong: { ja: "リスク管理とはリスクをゼロにすることだ。", en: "Risk management means eliminating all risk." },
      right: { ja: "リスク管理はアペタイト内に収めること。過度な回避は成長機会も逃す。残余リスクを許容水準へ。", en: "Risk management keeps risk within appetite; over-avoidance forgoes opportunity. Bring residual risk to tolerance." },
    },
    {
      id: "cf06",
      title: { ja: "会計利益 と 課税所得 と キャッシュ", en: "Accounting Profit vs Taxable Income vs Cash" },
      wrong: { ja: "会計利益・課税所得・キャッシュフローは同じ。", en: "Accounting profit, taxable income, and cash are the same." },
      right: { ja: "三者は別物。税務調整で課税所得が、運転資本・投資でキャッシュが会計利益と乖離する。", en: "All three differ: tax adjustments shift taxable income, and working capital/capex shift cash from profit." },
    },
  );
